function doGet(e) {
  var action = (e && e.parameter && e.parameter.action) ? e.parameter.action : "get_all";
  var callback = (e && e.parameter && e.parameter.callback) ? e.parameter.callback : "";
  
  if (action === "ping" || action === "test") {
    var res = { status: "success", message: "Google Sheet Connected!" };
    return sendResponse(res, callback);
  }

  if (action === "restore_headers") {
    restoreHeaders();
    return sendResponse({ status: "success", message: "Headers restored successfully!" }, callback);
  }

  if (action === "setup_sheets") {
    setupSheets();
    return sendResponse({ status: "success", message: "Sheets setup completed with 1856 territories!" }, callback);
  }

  try {
    var ss = SpreadsheetApp.getActiveSpreadsheet();
    var pair = getOrCreateSheets(ss);
    var sheet1 = pair.sheet1;
    var sheet2 = pair.sheet2;
    var store = {};
    var populatedCount = 0;

    if (sheet1) {
      var lr1 = sheet1.getLastRow();
      if (lr1 > 2) {
        var v1 = sheet1.getRange(3, 1, lr1 - 2, 16).getValues();
        for (var i = 0; i < v1.length; i++) {
          var code = String(v1[i][4]).trim();
          if (code) {
            if (!store[code]) store[code] = {};
            var doc_name = String(v1[i][6] || "").trim();
            var doc_rpl = String(v1[i][7] || "").trim();
            var m1_sw = String(v1[i][8] || "").trim();
            var m1_sz = String(v1[i][9] || "").trim();
            var m2_sw = String(v1[i][10] || "").trim();
            var m2_sz = String(v1[i][11] || "").trim();
            var m3_sw = String(v1[i][12] || "").trim();
            var m3_sz = String(v1[i][13] || "").trim();
            var m4_sw = String(v1[i][14] || "").trim();
            var m4_sz = String(v1[i][15] || "").trim();

            store[code].c1_doc_name = doc_name;
            store[code].c1_doc_rpl = doc_rpl;
            store[code].c1_m1_sweater = m1_sw;
            store[code].c1_m1_size = m1_sz;
            store[code].c1_m2_sweater = m2_sw;
            store[code].c1_m2_size = m2_sz;
            store[code].c1_m3_sweater = m3_sw;
            store[code].c1_m3_size = m3_sz;
            store[code].c1_m4_sweater = m4_sw;
            store[code].c1_m4_size = m4_sz;
          }
        }
      }
    }

    if (sheet2) {
      var lr2 = sheet2.getLastRow();
      if (lr2 > 2) {
        var v2 = sheet2.getRange(3, 1, lr2 - 2, 22).getValues();
        for (var j = 0; j < v2.length; j++) {
          var code2 = String(v2[j][4]).trim();
          if (code2) {
            if (!store[code2]) store[code2] = {};
            var d1_name = String(v2[j][6] || "").trim();
            var d1_rpl = String(v2[j][7] || "").trim();
            var d1_sw = String(v2[j][8] || "").trim();
            var d1_sz = String(v2[j][9] || "").trim();
            var d2_name = String(v2[j][10] || "").trim();
            var d2_rpl = String(v2[j][11] || "").trim();
            var d2_sw = String(v2[j][12] || "").trim();
            var d2_sz = String(v2[j][13] || "").trim();
            var d3_name = String(v2[j][14] || "").trim();
            var d3_rpl = String(v2[j][15] || "").trim();
            var d3_sw = String(v2[j][16] || "").trim();
            var d3_sz = String(v2[j][17] || "").trim();
            var d4_name = String(v2[j][18] || "").trim();
            var d4_rpl = String(v2[j][19] || "").trim();
            var d4_sw = String(v2[j][20] || "").trim();
            var d4_sz = String(v2[j][21] || "").trim();

            store[code2].c2_d1_name = d1_name;
            store[code2].c2_d1_rpl = d1_rpl;
            store[code2].c2_d1_sweater = d1_sw;
            store[code2].c2_d1_size = d1_sz;
            store[code2].c2_d2_name = d2_name;
            store[code2].c2_d2_rpl = d2_rpl;
            store[code2].c2_d2_sweater = d2_sw;
            store[code2].c2_d2_size = d2_sz;
            store[code2].c2_d3_name = d3_name;
            store[code2].c2_d3_rpl = d3_rpl;
            store[code2].c2_d3_sweater = d3_sw;
            store[code2].c2_d3_size = d3_sz;
            store[code2].c2_d4_name = d4_name;
            store[code2].c2_d4_rpl = d4_rpl;
            store[code2].c2_d4_sweater = d4_sw;
            store[code2].c2_d4_size = d4_sz;
          }
        }
      }
    }

    for (var k in store) {
      var item = store[k];
      if (item.c1_doc_name || item.c1_doc_rpl || item.c1_m1_sweater || item.c2_d1_name || item.c2_d1_rpl || item.c2_d1_sweater) {
        populatedCount++;
      }
    }

    return sendResponse({
      status: "success",
      store: store,
      total_territories: Object.keys(store).length,
      populated_territories: populatedCount
    }, callback);

  } catch (err) {
    return sendResponse({ status: "error", message: err.toString() }, callback);
  }
}

function sendResponse(obj, callback) {
  var jsonStr = JSON.stringify(obj);
  if (callback && callback.trim()) {
    return ContentService
      .createTextOutput(callback.trim() + "(" + jsonStr + ");")
      .setMimeType(ContentService.MimeType.JAVASCRIPT);
  }
  return ContentService
    .createTextOutput(jsonStr)
    .setMimeType(ContentService.MimeType.JSON);
}

function doPost(e) {
  try {
    var rawText = (e && e.postData && e.postData.contents) ? e.postData.contents : "";
    var postData = rawText ? JSON.parse(rawText) : (e ? e.parameter : {});
    var action = postData.action || "save_territory";
    var ss = SpreadsheetApp.getActiveSpreadsheet();

    if (action === "save_territory") {
      updateTerritoryInSheets(ss, String(postData.sap_territory_code), postData.data);
      return ContentService.createTextOutput(JSON.stringify({ status: "success" })).setMimeType(ContentService.MimeType.JSON);
    }
    
    if (action === "save_batch") {
      var batch = postData.batch || {};
      for (var tCode in batch) {
        updateTerritoryInSheets(ss, String(tCode), batch[tCode]);
      }
      return ContentService.createTextOutput(JSON.stringify({ status: "success", count: Object.keys(batch).length })).setMimeType(ContentService.MimeType.JSON);
    }

    if (action === "delete_region") {
      clearRegionSheetData(ss, String(postData.sap_region_code));
      return ContentService.createTextOutput(JSON.stringify({ status: "success", message: "Region cleared" })).setMimeType(ContentService.MimeType.JSON);
    }

    if (action === "reset_all") {
      clearAllSheetData(ss);
      return ContentService.createTextOutput(JSON.stringify({ status: "success", message: "All sheet data reset" })).setMimeType(ContentService.MimeType.JSON);
    }

    return ContentService.createTextOutput(JSON.stringify({ status: "error", message: "Unknown action" })).setMimeType(ContentService.MimeType.JSON);
  } catch (err) {
    return ContentService.createTextOutput(JSON.stringify({ status: "error", message: err.toString() })).setMimeType(ContentService.MimeType.JSON);
  }
}

function updateTerritoryInSheets(ss, terrCode, d) {
  if (!d || !terrCode) return;
  var pair = getOrCreateSheets(ss);
  var sheet1 = pair.sheet1;
  var sheet2 = pair.sheet2;

  if (sheet1) {
    var lr1 = sheet1.getLastRow();
    if (lr1 > 2) {
      var codes1 = sheet1.getRange(3, 5, lr1 - 2, 1).getValues();
      for (var i = 0; i < codes1.length; i++) {
        if (String(codes1[i][0]).trim() === String(terrCode).trim()) {
          var v1 = [d.c1_doc_name||"", d.c1_doc_rpl||"", d.c1_m1_sweater||"", d.c1_m1_size||"", d.c1_m2_sweater||"", d.c1_m2_size||"", d.c1_m3_sweater||"", d.c1_m3_size||"", d.c1_m4_sweater||"", d.c1_m4_size||""];
          sheet1.getRange(i + 3, 7, 1, 10).setValues([v1]);
          break;
        }
      }
    }
  }

  if (sheet2) {
    var lr2 = sheet2.getLastRow();
    if (lr2 > 2) {
      var codes2 = sheet2.getRange(3, 5, lr2 - 2, 1).getValues();
      for (var j = 0; j < codes2.length; j++) {
        if (String(codes2[j][0]).trim() === String(terrCode).trim()) {
          var v2 = [d.c2_d1_name||"", d.c2_d1_rpl||"", d.c2_d1_sweater||"", d.c2_d1_size||"", d.c2_d2_name||"", d.c2_d2_rpl||"", d.c2_d2_sweater||"", d.c2_d2_size||"", d.c2_d3_name||"", d.c2_d3_rpl||"", d.c2_d3_sweater||"", d.c2_d3_size||"", d.c2_d4_name||"", d.c2_d4_rpl||"", d.c2_d4_sweater||"", d.c2_d4_size||""];
          sheet2.getRange(j + 3, 7, 1, 16).setValues([v2]);
          break;
        }
      }
    }
  }
}

function clearRegionSheetData(ss, regCode) {
  if (!regCode) return;
  var pair = getOrCreateSheets(ss);
  var sheet1 = pair.sheet1;
  var sheet2 = pair.sheet2;

  if (sheet1) {
    var lr1 = sheet1.getLastRow();
    if (lr1 > 2) {
      var rCodes1 = sheet1.getRange(3, 2, lr1 - 2, 1).getValues();
      for (var i = 0; i < rCodes1.length; i++) {
        if (String(rCodes1[i][0]).trim() === String(regCode).trim()) {
          var v1 = ["", "", "", "", "", "", "", "", "", ""];
          sheet1.getRange(i + 3, 7, 1, 10).setValues([v1]);
        }
      }
    }
  }

  if (sheet2) {
    var lr2 = sheet2.getLastRow();
    if (lr2 > 2) {
      var rCodes2 = sheet2.getRange(3, 2, lr2 - 2, 1).getValues();
      for (var j = 0; j < rCodes2.length; j++) {
        if (String(rCodes2[j][0]).trim() === String(regCode).trim()) {
          var v2 = ["", "", "", "", "", "", "", "", "", "", "", "", "", "", "", ""];
          sheet2.getRange(j + 3, 7, 1, 16).setValues([v2]);
        }
      }
    }
  }
}

function clearAllSheetData(ss) {
  var pair = getOrCreateSheets(ss);
  var sheet1 = pair.sheet1;
  var sheet2 = pair.sheet2;

  restoreHeaders();

  if (sheet1) {
    var lr1 = sheet1.getLastRow();
    if (lr1 > 2) {
      sheet1.getRange(3, 7, lr1 - 2, 10).clearContent();
    }
  }

  if (sheet2) {
    var lr2 = sheet2.getLastRow();
    if (lr2 > 2) {
      sheet2.getRange(3, 7, lr2 - 2, 16).clearContent();
    }
  }
}
